"""Internal eight-course CPS exam specification; no provider bindings."""
import json
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from schools.exam_blueprints import validate_blueprint
CODES = ['SWP-001', 'SWP-002', 'SWP-003', *[f'SWP-{n:03}' for n in range(66, 71)]]


def blueprint():
    catalogue = json.loads((ROOT / 'production_courseware/release-2026-10-03/course_catalogue.json').read_text())
    rows = catalogue['courses'] if isinstance(catalogue, dict) else catalogue
    retained = {r['code']: {k: r[k] for k in ('title', 'outcome', 'modules', 'cbt_focus')} for r in rows if r['code'] in CODES[:3]}
    items = [dict(id=f'CPS8-{code}-MCQ-{n:02}', type='MCQ', marks=1, course_codes=[code], question_binding=None) for code in CODES for n in range(1, 6)]
    short = [
        (CODES[:3], 'A fictional family plan treats poverty alone as proof that a child must leave home. A possible kinship caregiver has not been assessed; reunification is promised after one meeting. Give five corrections within an introductory learner role.',
         'Distinguish concerns, risks and actual safety needs; consider family strengths, support and a reviewed safety plan; assess kinship suitability and support; consider child views, contact and context; and treat reunification/permanency as reviewed decisions for authorised practitioners, not promises or learner determinations.',
         ['Concern and immediate safety reasoning (001)', 'Family strengths support and safety review (002)', 'Kinship suitability and support (002)', 'Child voice contact and context (002/003)', 'Readiness reviewed permanency and qualified authority (003)']),
        ([CODES[3]], 'In a fictional planning meeting an adult answers for a child who communicates differently. A vote is described as consent and no one explains what can change. Give five improvements.',
         'Clarify decision influence; offer appropriate communication support and alternatives without assuming inability; support a voluntary view without forced disclosure; explain realistic information boundaries without inferring consent from a vote or silence; and record how views were considered with an accessible response and review route. Voice alone does not prove safety or transfer adult responsibility.',
         ['Honest influence', 'Accessible communication', 'Voluntary voice', 'Information limits and no inferred consent', 'Response review and adult responsibility']),
        ([CODES[4]], 'A fictional case spreadsheet is shared with every partner, includes names in a classroom example, has no update owner and marks a referral successful once an email is sent. Give five corrections.',
         'Keep coursework entirely invented; define purpose, minimum necessary information and authorised access; verify applicable consent/assent, lawful grounds and confidentiality limits through qualified local procedures; maintain accountable accurate records and controlled handover; and verify referral follow-up without assuming transmission proves access, benefit or completed casework.',
         ['Fictional coursework only', 'Purpose proportionality and authorised access', 'Contextual authority consent and limits', 'Accuracy ownership and handover', 'Referral follow-up and no assumed benefit']),
        ([CODES[5]], 'A fictional organisation relies on a policy poster and one screening certificate. A volunteer handles a complaint about their own conduct; partners have no reporting arrangements. Give five corrections.',
         'Connect policy to assigned operational responsibilities; use contextual safer recruitment, conduct, induction and supervision without treating one check as a guarantee; provide accessible bounded reporting and qualified safeguarding routes; address conflicts through an authorised impartial response rather than learner investigation; and review partner responsibilities, implementation and follow-up. Low report counts do not prove safety.',
         ['Operational responsibilities', 'Safer people arrangements', 'Accessible qualified reporting', 'Conflict and authorised scope', 'Partner accountability and cautious counts']),
        ([CODES[6]], 'A fictional facilitator proposes unlicensed therapy based on a research abstract, claims caregiver improvement proves child mental-health benefit, and blames a caregiver for a cross-sectional association. Give five corrections.',
         'Keep learning fictional and within role; distinguish supportive referral from clinical or specialist delivery requiring competence and authority; interpret association without causal or blame claims; distinguish caregiver, violence and child outcomes; and assess setting, design, reporting, follow-up and implementation limits. The 2026 displacement trial did not establish child emotional/behavioural benefit.',
         ['Fictional bounded learning', 'Qualified delivery authority', 'Association is not causation or blame', 'Outcome-specific interpretation', 'Context methods and implementation limits']),
        ([CODES[7]], 'A fictional emergency desk publishes names of separated children, offers reunification without verification and asks untrained learners to deploy. Give five corrections.',
         'Prioritise safe inclusive access through designated competent arrangements; restrict identifying information by authorised purpose and controls; refer separation concerns to qualified coordinated services without arranging unverified reunification; examine cross-sector access, communication and unintended risks; and keep coursework a conditional simulation with responsibilities and review, not deployment authority.',
         ['Inclusive safety and competent arrangements', 'Controlled necessary information', 'Qualified separation response', 'Cross-sector access and risks', 'Simulation responsibilities and review']),
    ]
    for n, (coverage, prompt, model, criteria) in enumerate(short, 1):
        items.append(dict(id=f'CPS8-SA-{n:02}', type='SHORT_ANSWER', marks=5, course_codes=coverage, prompt=prompt, model_answer=model, rubric=[dict(criterion=x, marks=1, scoring='0 absent/unsafe/unsupported; 1 accurate relevant reasoning applied to the fictional case. Accept equivalent defensible reasoning.') for x in criteria], human_marking_required=True))
    essays = [
        ('Develop a conditional review plan across all eight CPS courses for a fictional family-support programme in a displacement setting. Material hardship is treated as grounds for separation; kinship support is unassessed; reunification is promised; communication needs are overlooked; partner data are shared openly; volunteer supervision and reporting routes are unclear; and a caregiver-support abstract is treated as a delivery manual. Explain priorities, responsibilities, evidence, review and introductory-learning limits.',
         'Integrate concern recognition and immediate safety boundaries; family strengths, support and reviewed safety planning; assessed kinship and evidence-informed permanency; supported voluntary child voice with honest influence and feedback; necessary controlled information and accountable referral; safer organisational people, reporting, partners and supervision; outcome-specific research interpretation without blame or unauthorised treatment; and coordinated inclusive emergency services with separation safeguards. Set conditional owners, unresolved approvals and review points. Do not recruit children, investigate, disclose real records, promise placement or claim deployment competence.'),
        ('Critique a fictional claim of proven child safety based on a policy poster, fewer complaints, attendance, caregiver self-reports and a participation vote. The programme offers instant reunification, calls a public case spreadsheet transparent, and promises certification after reading slides. Use all eight CPS domains to propose corrections and identify missing evidence and authority.',
         'Separate concern recognition from proof of safety, family support from automatic separation, and assessed permanency from promises. Explain accessible child influence without inferred consent; necessary sharing and accountable case-information practice; operational safeguarding beyond posters and counts; association, self-report, outcome and transfer limits in parenting evidence; and qualified coordinated emergency decisions. Require contextual evidence, competent responsibilities, feedback, supervision and review. Reading alone confers no badge or certificate: verified course passes, a configured mixed ParaLearn exam, criterion-level human marking, independent moderation, completion and authorised signatures remain required.'),
    ]
    criteria = [('Concern recognition family preservation kinship and reviewed permanency (001/002/003)', 3), ('Accessible voluntary child voice influence and response (066)', 3), ('Necessary controlled information accountable referral and scope (067)', 3), ('Organisational safeguarding and prevention evidence (068/069)', 3), ('Inclusive coordinated emergency response authority and coherent review (070)', 3)]
    for n, (prompt, model) in enumerate(essays, 1):
        items.append(dict(id=f'CPS8-ESSAY-{n:02}', type='ESSAY', marks=15, course_codes=CODES, prompt=prompt, model_answer=model, human_marking_required=True, rubric=[dict(criterion=x, marks=w, scoring='0 absent/unsafe; 1 relevant limited point; 2 defensible applied reasoning with a gap; 3 coherent contextual reasoning with feasible action, authority and evidence limits. Accept equivalent defensible reasoning.') for x, w in criteria]))
    return dict(status='draft_for_review', school_code='CPS', curriculum_version='CPS-proposed-eight-course-0.1.0', provider='ParaLearn CBT', provider_assessment_id=None, provider_contract_verified=False, required_courses=CODES, programme_target_course_count=8, draft_catalogue_complete=True, curriculum_complete=False, remaining_curriculum_titles=[], retained_course_domains=retained,
        scope_note='Eight-title internal assessment map. Original 001-003 teaching and CBTs remain unchanged. Learning materials may be owner-approved separately; local protocols, competence, provider configuration, human marking and certification remain separate gates.',
        proposed_duration_minutes=210, duration_status='Proposed; accessibility review and learner piloting pending',
        marking_policy=dict(proposed_pass_percent=70, moderation_required=True, ai_only_finalisation=False, rubric_rule='Human criterion-level scores and reasons; independent identified human moderator checks written marks and amendments. Retain response, rubric version, marker, moderator and amendment/appeal history. Accept equivalent defensible reasoning; no automatic professional-competence decision.', appeals='Authorised review retains response, criterion scores, reasons, moderation, dated amendments and outcome.'),
        certification=dict(authorised=False, requirements=['Course badge: approved course plus verified ParaLearn course CBT pass', 'Certificate: all approved school courses plus final mixed ParaLearn exam with human written marking and independent moderation', 'Head of Learning name/signature pending; Founder Prof. Mina Ogbanga; authorised signatures required']), items=items)


if __name__ == '__main__':
    data = blueprint()
    print(validate_blueprint(data))
    (ROOT / 'production_courseware/phase_eleven/cps_batch_01/school_exam_blueprint.json').write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
